function updatePorts(nodeId, parameters, editorConnection, graphModel) {
  var ports = [];

  let dbCollections = graphModel.getMetaData('dbCollections');
  const systemCollections = graphModel.getMetaData('systemCollections');

  console.log('[DbCollectionNode] updatePorts called for node:', nodeId);
  console.log('[DbCollectionNode] dbCollections:', dbCollections);
  console.log('[DbCollectionNode] systemCollections:', systemCollections);

  // NEW: Trigger Supabase table discovery if no collections are found or if Supabase tables are missing
  const supabaseTablesExist = dbCollections && dbCollections.some(c => c._isSupabaseTable);

  if (!dbCollections || dbCollections.length === 0 || !supabaseTablesExist) {
    if (!supabaseTablesExist && dbCollections && dbCollections.length > 0) {
      console.log('[DbCollectionNode] Supabase tables missing from collections, attempting recovery...');
    } else {
      console.log('[DbCollectionNode] No dbCollections found, triggering Supabase discovery...');
    }
    try {
      // Try multiple ways to access CloudStore
      let cloudStore = null;

      // Method 1: Try global CloudStore instance
      if (CloudStore && CloudStore.instance) {
        cloudStore = CloudStore.instance;
        console.log('[DbCollectionNode] Using CloudStore.instance');
      }

      // Method 2: Try via xgeniaRuntime
      if (!cloudStore && xgeniaRuntime && xgeniaRuntime.instance && xgeniaRuntime.instance.cloudStore) {
        cloudStore = xgeniaRuntime.instance.cloudStore;
        console.log('[DbCollectionNode] Using xgeniaRuntime.instance.cloudStore');
      }

      // Method 3: Try creating a new instance for this scope
      if (!cloudStore) {
        try {
          cloudStore = CloudStore.forScope();
          console.log('[DbCollectionNode] Created new CloudStore instance');
        } catch (createError) {
          console.warn('[DbCollectionNode] Failed to create CloudStore:', createError);
        }
      }

      if (cloudStore && cloudStore.supabaseClient) {
        console.log('[DbCollectionNode] Attempting to discover Supabase tables...');

        // First try to restore from localStorage if tables were recently discovered
        let discoveredTables = [];
        if (!supabaseTablesExist) {
          try {
            const restoredTables = cloudStore._restoreTablesFromStorage();
            if (restoredTables.length > 0) {
              console.log(`[DbCollectionNode] Restored ${restoredTables.length} tables from localStorage`);
              cloudStore._updateDbCollectionsMetadata(restoredTables);
              discoveredTables = restoredTables;
            }
          } catch (restoreError) {
            console.warn('[DbCollectionNode] Failed to restore tables:', restoreError);
          }
        }

        // If no restored tables, do fresh discovery
        if (discoveredTables.length === 0) {
          discoveredTables = await cloudStore._discoverAndRegisterSupabaseTables();
        }

        if (discoveredTables && discoveredTables.length > 0) {
          console.log('[DbCollectionNode] Successfully got tables, refreshing metadata...');
          // Refresh dbCollections after discovery
          dbCollections = graphModel.getMetaData('dbCollections');
          console.log('[DbCollectionNode] Updated dbCollections:', dbCollections);

          // IMPORTANT: Force a return here to regenerate ports with new data
          return updatePorts(nodeId, parameters, editorConnection, graphModel);
        }
      } else {
        console.warn('[DbCollectionNode] CloudStore or Supabase client not available:', {
          cloudStore: !!cloudStore,
          supabaseClient: !!cloudStore?.supabaseClient
        });
      }
    } catch (error) {
      console.warn('[DbCollectionNode] Error during Supabase table discovery:', error);
    }
  }

  const _systemClasses = [
    { label: 'User', value: '_User' },
    { label: 'Role', value: '_Role' }
  ];

  // Build the collection options
  const collectionOptions = _systemClasses.concat(
    dbCollections !== undefined
      ? dbCollections.map((c) => {
          return { value: c.name, label: c.name };
        })
      : []
  );

  console.log('[DbCollectionNode] Final collection options:', collectionOptions);

  ports.push({
    name: 'collectionName',
    type: {
      name: 'enum',
      enums: collectionOptions,
      allowEditOnly: true
    },
    displayName: 'Class',
    plug: 'input',
    group: 'General'
  });

  ports.push({
    name: 'storageFilterType',
    type: {
      name: 'enum',
      allowEditOnly: true,
      enums: [
        { value: 'simple', label: 'Visual' },
        { value: 'json', label: 'Javascript' }
      ]
    },
    displayName: 'Filter',
    default: 'simple',
    plug: 'input',
    group: 'General'
  });

  // Limit
  ports.push({
    type: 'boolean',
    plug: 'input',
    group: 'Limit',
    name: 'storageEnableLimit',
    displayName: 'Use limit'
  });

  if (parameters['storageEnableLimit']) {
    ports.push({
      type: 'number',
      default: 10,
      plug: 'input',
      group: 'Limit',
      name: 'storageLimit',
      displayName: 'Limit'
    });

    ports.push({
      type: 'number',
      default: 0,
      plug: 'input',
      group: 'Limit',
      name: 'storageSkip',
      displayName: 'Skip'
    });
  }

  ports.push({
    type: 'signal',
    plug: 'input',
    group: 'Actions',
    name: 'storageFetch',
    displayName: 'Do'
  });

  // Total Count
  ports.push({
    type: 'boolean',
    plug: 'input',
    group: 'Total Count',
    name: 'storageEnableCount',
    displayName: 'Fetch total count'
  });

  if (parameters['storageEnableCount']) {
    ports.push({
      type: 'number',
      plug: 'output',
      group: 'General',
      name: 'storageTotalCount',
      displayName: 'Total Count'
    });
  }

  // Simple query
  if (parameters['storageFilterType'] === undefined || parameters['storageFilterType'] === 'simple') {
    if (parameters.collectionName !== undefined) {
      var c = dbCollections && dbCollections.find((c) => c.name === parameters.collectionName);
      if (c === undefined && systemCollections) c = systemCollections.find((c) => c.name === parameters.collectionName);
      if (c && c.schema && c.schema.properties) {
        const schema = JSON.parse(JSON.stringify(c.schema));

        // Find all records that have a relation with this type
        function _findRelations(c) {
          if (c.schema !== undefined && c.schema.properties !== undefined)
            for (var key in c.schema.properties) {
              var p = c.schema.properties[key];
              if (p.type === 'Relation' && p.targetClass === parameters.collectionName) {
                if (schema.relations === undefined) schema.relations = {};
                if (schema.relations[c.name] === undefined) schema.relations[c.name] = [];

                schema.relations[c.name].push({ property: key });
              }
            }
        }

        dbCollections && dbCollections.forEach(_findRelations);
        systemCollections && systemCollections.forEach(_findRelations);

        ports.push({
          name: 'visualFilter',
          plug: 'input',
          type: { name: 'query-filter', schema: schema, allowEditOnly: true },
          displayName: 'Filter',
          group: 'Filter'
        });

        ports.push({
          name: 'visualSort',
          plug: 'input',
          type: { name: 'query-sorting', schema: schema, allowEditOnly: true },
          displayName: 'Sort',
          group: 'Sorting'
        });
      }

      if (parameters.visualFilter !== undefined) {
        // Find all input ports
        const uniqueInputs = {};
        function _collectInputs(query) {
          if (query === undefined) return;
          if (query.rules !== undefined) query.rules.forEach((r) => _collectInputs(r));
          else if (query.input !== undefined) uniqueInputs[query.input] = true;
        }

        _collectInputs(parameters.visualFilter);
        Object.keys(uniqueInputs).forEach((input) => {
          ports.push({
            name: 'qp-' + input,
            plug: 'input',
            type: '*',
            displayName: input,
            group: 'Query Parameters'
          });
        });
      }
    }
  }
  // JSON query
  else if (parameters['storageFilterType'] === 'json') {
    ports.push({
      type: { name: 'string', allowEditOnly: true, codeeditor: 'javascript' },
      plug: 'input',
      group: 'Filter',
      name: 'storageJSONFilter',
      default: _defaultJSONQuery,
      displayName: 'Filter'
    });

    var filter = parameters['storageJSONFilter'];
    if (filter) {
      filter = filter.replace(/\/\*[\s\S]*?\*\/|\/\/.*/g, ''); // Remove comments
      var variables = filter.match(/\$[A-Za-z0-9]+/g);

      if (variables) {
        const unique = {};
        variables.forEach((v) => {
          unique[v] = true;
        });

        Object.keys(unique).forEach((p) => {
          ports.push({
            name: 'storageFilterValue-' + p.substring(1),
            displayName: p.substring(1),
            group: 'Filter Values',
            plug: 'input',
            type: { name: '*', allowConnectionsOnly: true }
          });
        });
      }

      // Support variables with the "Inputs."" syntax
      JavascriptNodeParser.parseAndAddPortsFromScript(filter, ports, {
        inputPrefix: 'storageFilterValue-',
        inputGroup: 'Filter Values',
        inputType: { name: '*', allowConnectionsOnly: true },
        skipOutputs: true
      });
    }
  }

  editorConnection.sendDynamicPorts(nodeId, ports);
}

