function _managePortsForNode(node) {
      // Handle async updatePorts calls
      updatePorts(node.id, node.parameters, context.editorConnection, graphModel).catch((error) => {
        console.warn('[DbCollectionNode] Error in initial updatePorts:', error);
      });

      node.on('parameterUpdated', function (event) {
        if (event.name.startsWith('storage') || event.name === 'visualFilter' || event.name === 'collectionName') {
          updatePorts(node.id, node.parameters, context.editorConnection, graphModel).catch((error) => {
            console.warn('[DbCollectionNode] Error in parameterUpdated updatePorts:', error);
          });
        }
      });

      graphModel.on('metadataChanged.dbCollections', function (data) {
        console.log('[DbCollectionNode] metadataChanged.dbCollections event received:', data);
        CloudStore.invalidateCollections();
        console.log('[DbCollectionNode] Invalidated collections cache, updating ports...');
        updatePorts(node.id, node.parameters, context.editorConnection, graphModel)
          .then(() => {
            console.log('[DbCollectionNode] Ports updated for node:', node.id);
          })
          .catch((error) => {
            console.warn('[DbCollectionNode] Error in metadataChanged.dbCollections updatePorts:', error);
          });
      });

      graphModel.on('metadataChanged.systemCollections', function (data) {
        CloudStore.invalidateCollections();
        updatePorts(node.id, node.parameters, context.editorConnection, graphModel).catch((error) => {
          console.warn('[DbCollectionNode] Error in metadataChanged.systemCollections updatePorts:', error);
        });
      });

      graphModel.on('metadataChanged.cloudservices', function (data) {
        CloudStore.instance._initCloudServices();
        // Trigger port update after cloud services change to refresh table list
        updatePorts(node.id, node.parameters, context.editorConnection, graphModel).catch((error) => {
          console.warn('[DbCollectionNode] Error in metadataChanged.cloudservices updatePorts:', error);
        });
      });
    }
